from AlgorithmImports import *
import math


class ExactStrategyAlgorithm(QCAlgorithm):
    SMA_PERIOD = 200
    RSI_PERIOD = 14
    AAPL_BUY_AMOUNT = 20000

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(
            self.spy,
            self.SMA_PERIOD,
            Resolution.Daily
        )

        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(self.SMA_PERIOD + 1, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False
        self.order_strategy = {}

    def OnData(self, data):
        spy_bar = self._get_bar(data, self.spy)
        aapl_bar = self._get_bar(data, self.aapl)

        spy_cross_above = False
        spy_cross_below = False

        if spy_bar is not None:
            spy_close = float(spy_bar.Close)

            if self.spy_sma.IsReady:
                current_sma = float(self.spy_sma.Current.Value)

                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                ):
                    spy_cross_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_close > current_sma
                    )

                    spy_cross_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < current_sma
                    )

                self.previous_spy_sma = current_sma

            self.previous_spy_close = spy_close

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if not all(self._get_bar(data, symbol) is not None for symbol in self.symbols):
            return

        if self.IsWarmingUp:
            return

        aapl_rsi_above_60 = (
            self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60.0
        )

        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_pending
            and spy_cross_below
        ):
            self._submit_order(
                "A",
                self.spy,
                -self.strategy_a_lot,
                "STRATEGY_A_SELL"
            )

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_pending
            and aapl_rsi_above_60
        ):
            self._submit_order(
                "B",
                self.aapl,
                -self.strategy_b_lot,
                "STRATEGY_B_SELL"
            )

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_pending
            and spy_cross_above
        ):
            spy_close = float(spy_bar.Close)
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            quantity = int(math.floor(target_value / spy_close))

            if quantity > 0:
                self._submit_order(
                    "A",
                    self.spy,
                    quantity,
                    "STRATEGY_A_BUY"
                )

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_pending
            and self.aapl_red_streak >= 3
        ):
            aapl_close = float(aapl_bar.Close)

            if float(self.Portfolio.Cash) >= self.AAPL_BUY_AMOUNT:
                quantity = int(math.floor(self.AAPL_BUY_AMOUNT / aapl_close))

                if quantity > 0:
                    self._submit_order(
                        "B",
                        self.aapl,
                        quantity,
                        "STRATEGY_B_BUY"
                    )

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategy.get(order_event.OrderId)

        if strategy is None:
            tag = getattr(order_event, "Tag", "")
            if "STRATEGY_A" in tag:
                strategy = "A"
            elif "STRATEGY_B" in tag:
                strategy = "B"
            elif order_event.Symbol == self.spy:
                strategy = "A"
            elif order_event.Symbol == self.aapl:
                strategy = "B"

        if strategy is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if strategy == "A":
            self.strategy_a_lot = max(
                0,
                self.strategy_a_lot + fill_quantity
            )
        else:
            self.strategy_b_lot = max(
                0,
                self.strategy_b_lot + fill_quantity
            )

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if strategy == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False

    def _submit_order(self, strategy, symbol, quantity, tag):
        if quantity == 0:
            return

        if strategy == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            if strategy == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False
            return

        self.order_strategy[ticket.OrderId] = strategy

    def _get_bar(self, data, symbol):
        if data.Bars.ContainsKey(symbol):
            return data.Bars[symbol]
        return None
